    java.startBrowserAwait(baseUrl + '/user', '登录');
    var ck = String(cookie.getCookie(baseUrl) || '');
    if (ck && ck.indexOf('admin_session') >= 0) {
        java.toast('登录成功');
    } else {
        java.toast('未检测到登录状态，请在浏览器中完成登录后再关闭页面');
    }
}

function checkLogin() {
    var baseUrl = String(source.bookSourceUrl);
    var ck = String(cookie.getCookie(baseUrl) || '');
    if (ck && ck.indexOf('admin_session') >= 0) {
        try {
            var a = JSON.parse(java.ajax(baseUrl + '/user/api/dashboard'));
            var tip = '当前已登录\n账号：' + a.user.nickname + '\n每日总量：' + a.quota.daily_limit + '\n已使用：' + a.quota.daily_used + '\n设备：' + a.quota.active_sessions + '/' + a.quota.max_sessions;
            java.toast(tip);
        } catch (e) {
            java.toast('当前已登录（获取详情失败）');
        }
    } else {
        java.toast('当前未登录');
    }
}

