content = {
    childNode: [],  // 子节点数组
    childNodes: result.match(/nrid="([^"]+)";/) ? java.getElements("#"+result.match(/nrid="([^"]+)";/)[1]+"@p").toArray() : "",  // 根据匹配到的nrid获取子节点数组
    UpWz: function(m, i) {  // 定义UpWz函数，根据传入的参数进行计算返回值
        var k = Math.ceil((i + 1) % this.code);  // 对(i+1)与code取模并向上取整
        k = Math.ceil(m - k);  // 对m减去k并向上取整
        return k;
    },
    load: function() {  // 加载函数
        this.code = String(result).match(/codeurl="(\d+)"/)[1];  // 获取code值
        var e = String(java.base64Decode(java.getString('[name=client]@content'))).split(/[A-Z]+%/);  // 对字符串进行base64解码并按一定分隔符分割成数组
        for (var i = 0; i < e.length; i++) {  // 遍历数组
            var k = this.UpWz(e[i], i);  // 调用UpWz函数计算出k值
            this.childNode[k] = this.childNodes[i];  // 将计算后的值作为索引，将对应的子节点存入childNode数组
        }
    }
}

if(baseUrl.match(/verify/)){
    result = "如果没获取到目录，说明验证码不对，详情页刷新重新获取验证码";
} else {
    if(baseUrl.match(/\d+_2\.html/)){
        content.load();
        result = content.childNode.join("<br>");
    } else if(baseUrl.match(/\/\d+\.html/)){
        result = java.getElements("#articlecontent@p");
    } else {
        // 加载外部JS文件 cryptojs_min.js
        eval(String(java.ajax("http://danmeirouwen.net/17mb/js/jquery-1.9.1.min.js")));

        // 定义函数d(a, b)用于解密操作
        function d(a, b) {
            // 将b进行MD5加密并转换为字符串
            b = CryptoJS.MD5(b).toString();

            // 提取加密后字符串的前16位和后面部分作为iv和参数创建对象
            var d = CryptoJS.enc.Utf8.parse(b.substring(0, 16));
            var e = CryptoJS.enc.Utf8.parse(b.substring(16));

            // 使用AES解密算法对a进行解密，并将结果转换为字符串格式
            return CryptoJS.AES.decrypt(a, e, { iv: d, padding: CryptoJS.pad.Pkcs7 }).toString(CryptoJS.enc.Utf8);
        }

        // 使用正则表达式匹配出来的信息作为参数调用函数d，并将结果赋值给result变量
        result = eval(result.match(/(d\("[\s\S]+"\))\)/)[1]);
    }
}
</js>","imageStyle":"text","nextContentUrl":"text.下一页@href##.*\('(\d+)','(\d+)','(\d+)_(\d+)'\);##/$1/$2/$3_$4.html","replaceRegex":"##本章已阅读.+|第.+章|\s*本章尚未.*\s*"}

