    }

    u.checkPixiv = () => {
        let logs = []
        let checkThings = ["pixivCsrfToken", "pixivCookie", "pixivUid"]
        checkThings.forEach(item => {
            let text = `${getFromCache(item)? "✅" : "❌"} ${item}`
            logs.push(text)
            java.log(text)
        })
        if (logs.join("").split("❌").length >= 2) {
            sleepToast("⚠️ 登录状态\n 当前登录信息不完整，请重新登录\n或使用【备份恢复】恢复登录状态")
        }
    }

