    const {java} = this;
    let t = String(times);
    let key = "20211010-KlasdoufnrufGIjasdUXWpl7Kjs";
    let str = "st20211010233045t" + t;
    let data = java.HMacHex(str,"HmacSHA1",key);
    return data;
}

