{"chapterList":"<js>
var site = '' + source.bookSourceUrl;
while (site.length > 0 && site.charAt(site.length - 1) === '/') site = site.substring(0, site.length - 1);
function getBookId(url) {
  var m = ('' + url).match(/\/book\/(\d+)/);
  return m ? m[1] : '';
}
function absUrl(u) {
  u = '' + u;
  if (u.indexOf('http') === 0) return u;
  if (u.charAt(0) === '/') return site + u;
  return site + '/' + u;
}
function trimT(s) {
  s = '' + s;
  var i = 0, j = s.length;
  while (i < j && s.charAt(i) <= ' ') i++;
  while (j > i && s.charAt(j - 1) <= ' ') j--;
  return s.substring(i, j);
}
var map = {};
var ids = [];
function chId(href) {
  var m = ('' + href).match(/\/read\/\d+\/(\d+)\.html/);
  return m ? parseInt(m[1]) : 0;
}
function addCh(href, text) {
  href = absUrl(href);
  if (href.indexOf('/read/') < 0) return;
  var id = chId(href);
  if (!id) return;
  text = trimT(text);
  if (text === '开始阅读' || text === '立即阅读' || text === '首章') return;
  if (map[id]) {
    if (text) map[id].t = text;
    return;
  }
  map[id] = { h: href, t: text, id: id };
  ids.push(id);
}
function extractGrid(html) {
  html = '' + html;
  var idx = html.indexOf('nx-chapter-grid');
  if (idx < 0) return '';
  var sub = html.substring(idx);
  var end = sub.indexOf('nx-tags-cloud');
  if (end < 0) end = sub.indexOf('相邻推荐');
  if (end < 0) end = sub.indexOf('pagination');
  if (end < 0) end = Math.min(sub.length, 100000);
  return sub.substring(0, end);
}
function parsePage(html) {
  var grid = extractGrid(html);
  if (!grid) return;
  var re = /<a[^>]+href="(\/read\/[^"]+\.html)"[^>]*>([^<]*)<\/a>/gi;
  var m;
  while ((m = re.exec(grid)) !== null) addCh(m[1], m[2]);
}
function collectPages(html, bid) {
  var urls = [];
  var seen = {};
  function add(u) {
    u = absUrl(u);
    if (!u || seen[u]) return;
    seen[u] = 1;
    urls.push(u);
  }
  var maxP = 1;
  var re = new RegExp('/book/' + bid + '/(\\d+)\\.html', 'g');
  var m;
  while ((m = re.exec(html)) !== null) {
    var pn = parseInt(m[1]);
    if (pn > maxP) maxP = pn;
    add('/book/' + bid + '/' + pn + '.html');
  }
  add('/book/' + bid + '/1.html');
  for (var p = 2; p <= maxP; p++) add('/book/' + bid + '/' + p + '.html');
  return urls;
}
var html = src;
if (!html || ('' + html).indexOf('<') < 0) html = java.ajax(baseUrl);
html = '' + html;
var bid = getBookId(baseUrl);
if (!bid) bid = getBookId(html);
var pages = collectPages(html, bid);
parsePage(html);
for (var i = 0; i < pages.length; i++) {
  if (pages[i] === absUrl(baseUrl)) continue;
  parsePage('' + java.ajax(pages[i]));
}
ids.sort(function(a, b) { return a - b; });
var sbc = '';
for (var j = 0; j < ids.length; j++) {
  var ch = map[ids[j]];
