function trimSlash(s) {
  s = String(s);
  while (s.length > 0 && s.charAt(s.length - 1) === "/") s = s.substring(0, s.length - 1);
  return s;
}

function saveSite(name) {
  let cfg = SITES[name] || SITES["一夜春宵"];
  source.setVariable(trimSlash(cfg.url));
  cache.put("siteName", name);
  cache.put("siteMul", String(cfg.mul));
  return cfg;
}

function getSiteName() {
  return String(cache.get("siteName") || "一夜春宵");
}

// 登录页点击源站按钮切换
function pickSite(name) {
  let cfg = saveSite(name);
  java.longToast("已切换至: " + name + "\n" + cfg.url + "\n系数: " + cfg.mul);
  java.refreshExplore();
}

